            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/positions": {
          "get": {
            "summary": "Vessel position history",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/vessels/{id}": {
          "get": {
            "summary": "Vessel detail",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts/{id}": {
          "get": {
            "summary": "Alert detail / ack state",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts/{id}/ack": {
          "post": {
            "summary": "Acknowledge alert (commit)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
